// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/executors", wrapper.ListExecutors)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/repos", wrapper.ListRepos)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/repos", wrapper.CreateRepo)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/repos/discover", wrapper.DiscoverRepos)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/coding/repos/{repoId}/build-config", wrapper.SetRepoBuildConfig)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/coding/repos/{repoId}", wrapper.DeleteRepo)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/tasks", wrapper.ListTasks)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks", wrapper.CreateTask)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/tasks/{taskId}", wrapper.GetTask)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/tasks/{taskId}/events", wrapper.ListTaskEvents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks/{taskId}/cancel", wrapper.CancelTask)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/tasks/{taskId}/diff", wrapper.GetTaskDiff)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks/{taskId}/commit", wrapper.CommitTask)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks/{taskId}/push", wrapper.PushTask)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks/{taskId}/pr", wrapper.OpenPullRequest)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks/{taskId}/build", wrapper.BuildTask)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/tasks/{taskId}/artifacts/{index}", wrapper.DownloadTaskArtifact)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/coding/tasks/{taskId}/discard", wrapper.DiscardTask)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/coding/settings", wrapper.GetCodingSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/coding/settings", wrapper.UpdateCodingSettings)
	})

	return r
}
